def gp(q, Y, n, kern, rank=False):
    from scipy.linalg import cho_factor
    from scipy.linalg import cho_solve
    from scipy.optimize import minimize
    xx = q[:n]
    yc = Y[:n]
    ym = yc.mean(0)
    sd = yc.std(0)
    yc = (yc - ym) / sd
    D = (q[:, None, :] - xx[None, :, :]) ** 2

    def K(th):
        d = np.sqrt(np.maximum(D @ np.exp(th[:q.shape[1]]), 1e-15))
        if kern == 'rbf':
            return np.exp(-0.5 * d * d)
        if kern == 'm52':
            return (1 + d + d * d / 3) * np.exp(-d)
        if kern == 'rq':
            return (1 + 0.5 * d * d) ** (-1)

    def obj(th, ret=False):
        k = K(th)
        a = k[:n] + np.eye(n) * np.exp(th[-1])
        ch = cho_factor(a)
        al = cho_solve(ch, yc)
        if ret:
            return k @ al * sd + ym
        return 0.5 * np.sum(yc * al) + yc.shape[1] * np.log(np.diag(ch[0])).sum()
    r = minimize(obj, np.r_[np.zeros(q.shape[1]), -7.0], bounds=[(-8, 7)] * q.shape[1] + [(-13, -2)], method='L-BFGS-B')
    return (obj(r.x, True), r.x)

def basis(x, d):
    from itertools import combinations_with_replacement as C
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, i], 1) for k in range(1, d + 1) for i in C(range(x.shape[1]), k)])

def loo(x, y):
    e = y - x @ fit(x, y)
    h = (np.linalg.svd(x, full_matrices=False)[0] ** 2).sum(1)
    return e / (1 - h).reshape((-1,) + (1,) * (y.ndim - 1))

def profile(D, Y):
    e = loo(D, Y)
    return np.sqrt(np.mean(e * e, axis=0))
